function cocaPalletMarket(){const names=Object.keys(cities),day=offerCycleKey(),shuffled=[...names],rng=offerRandom('coca-pallet-'+day);for(let i=shuffled.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]]}const amount=Math.max(5,Math.min(10,Math.floor(names.length*.16))),sellers=shuffled.slice(0,amount).map((city,index)=>({city,price:Math.round((780+rng()*170)/10)*10,stock:3+Math.floor(rng()*5),side:'sell',index})),buyers=shuffled.slice(amount,amount*2).map((city,index)=>({city,price:Math.round((1180+rng()*270)/10)*10,demand:2+Math.floor(rng()*6),side:'buy',index}));return{day,sellers,buyers}}
function cocaOfferForCity(city){const market=cocaPalletMarket();return market.sellers.find(item=>item.city===city)||market.buyers.find(item=>item.city===city)||null}
function purchasedAssetsValue(){ensureTradeState();const trucks=ownedTruckIds().reduce((sum,id)=>sum+(Number(truckCatalog[id]?.price)||0),0),warehouses=Object.values(state.warehouses).filter(item=>item?.type==='owned').reduce((sum,item)=>sum+(Number(item.price)||WAREHOUSE_BUY_PRICE),0),pallets=[...state.truckPallets,...Object.values(state.warehouseStock).flatMap(items=>Array.isArray(items)?items:[])].reduce((sum,item)=>sum+(Number(item.cost)||0),0);return trucks+warehouses+pallets}
const deliveryPalletImages={CC:{image:'assets/items/coca-cola-pallet.png',alt:'Palete de produtos Coca-Cola',label:'PALETE DE COCA-COLA'},KL:{image:'assets/items/klabin-cellulose-pallet.png',alt:'Palete de celulose da Klabin',label:'PALETE DE CELULOSE'},FI:{image:'assets/items/fini-assorted-candy-pallet.png',alt:'Palete de diversos doces da Fini',label:'PALETE DE DIVERSOS DOCES'},BO:{image:'assets/items/bosch-drill-pallet.png',alt:'Palete de parafusadeiras Bosch Professional',label:'PALETE DE PARAFUSADEIRAS BOSCH'},PI:{image:'assets/items/pirelli-tire-pallet.png',alt:'Palete de pneus Pirelli',label:'PALETE DE PNEUS PIRELLI'}};
