function createMissionSet(period,target){const random=offerRandom((user?.uid||'motorista')+period),pool=missionPool(),pick=()=>pool[Math.floor(random()*pool.length)],shuffle=list=>{const copy=[...list];for(let i=copy.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy},allCities=[...new Set(pool.map(item=>item.city))],weekly=target>1,chooseCities=(count,excluded=[])=>shuffle(allCities.filter(city=>!excluded.includes(city))).slice(0,count),companyMission=pick(),originCities=chooseCities(weekly?3:1),destinationCities=chooseCities(weekly?3:1,originCities),cityText=list=>list.join(', ').replace(/, ([^,]*)$/, ' e $1'),makeCompany=item=>({id:'company-'+item.company.code+'-'+Math.floor(random()*1e6),kind:'company',company:item.company.name,title:'Entregue para '+item.company.name,description:'Conclua '+target+' entrega'+(target>1?'s':'')+' contratada'+(target>1?'s':'')+' pela empresa '+item.company.name+'.',progress:0,target,claimed:false}),makeRoute=(kind,list)=>({id:kind+'-'+Math.floor(random()*1e6),kind,cities:list,city:list[0],uniqueCities:weekly,title:(kind==='origin'?'Saia com uma encomenda de ':'Chegue com uma encomenda em ')+cityText(list),description:weekly?(kind==='origin'?'Faça uma entrega saindo de cada uma destas cidades: ':'Faça uma entrega chegando em cada uma destas cidades: ')+cityText(list)+'.':(kind==='origin'?'Pegue qualquer encomenda em '+list[0]+' e entregue em outra cidade.':'Chegue em '+list[0]+' com qualquer encomenda.')+' Faça isso 1 vez.',progress:0,target,claimed:false,completedCities:[]});return[makeCompany(companyMission),makeRoute('origin',originCities),makeRoute('destination',destinationCities)]}function ensureMissions(){const keys=missionPeriodKeys();state.missions=state.missions&&typeof state.missions==='object'?state.missions:{};let changed=false;if(state.missions.version!==2){state.missions={version:2};changed=true}if(state.missions.dailyKey!==keys.daily||!Array.isArray(state.missions.daily)){state.missions.dailyKey=keys.daily;state.missions.daily=createMissionSet('daily-'+keys.daily,1);changed=true}if(state.missions.weeklyKey!==keys.weekly||!Array.isArray(state.missions.weekly)){state.missions.weeklyKey=keys.weekly;state.missions.weekly=createMissionSet('weekly-'+keys.weekly,3);changed=true}state.missionPoints=Number(state.missionPoints)||0;return changed}
function missionMatches(mission,trip){if(mission.kind==='company')return trip.company===mission.company;if(mission.kind==='city'||mission.kind==='origin')return (mission.cities||[mission.city]).includes(trip.from);if(mission.kind==='destination')return (mission.cities||[mission.city]).includes(trip.to);return false}
function updateMissions(trip){ensureMissions();let gained=0;for(const [cycle,reward] of [['daily',1],['weekly',5]])for(const mission of state.missions[cycle])if(!mission.claimed&&missionMatches(mission,trip)){const matchedCity=mission.kind==='destination'?trip.to:(mission.kind==='origin'||mission.kind==='city'?trip.from:'');if(mission.uniqueCities){mission.completedCities=Array.isArray(mission.completedCities)?mission.completedCities:[];if(mission.completedCities.includes(matchedCity))continue;mission.completedCities.push(matchedCity)}mission.progress=Math.min(mission.target,(Number(mission.progress)||0)+1);if(mission.progress>=mission.target){mission.claimed=true;state.missionPoints+=reward;gained+=reward}}return gained}
function nextMissionReset(type){const now=new Date(),p=brazilNow(),base=new Date(Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute,+p.second));let reset;if(type==='daily'){reset=new Date(base);reset.setUTCDate(reset.getUTCDate()+1);reset.setUTCHours(0,0,0,0)}else{reset=new Date(base);const days=(3-reset.getUTCDay()+7)%7||7;reset.setUTCDate(reset.getUTCDate()+days);reset.setUTCHours(0,0,0,0)}return reset-base}
function missionCard(mission,reward){const pct=Math.min(100,Math.round((mission.progress/mission.target)*100));return'<article class="mission-card '+(mission.claimed?'done':'')+'"><header><span>'+(mission.claimed?'CONCLUÍDA':'EM ANDAMENTO')+'</span><b>+'+reward+' PT'+(reward>1?'S':'')+'</b></header><h3>'+escapeHTML(mission.title)+'</h3><p>'+escapeHTML(mission.description)+'</p><div class="mission-progress"><i style="width:'+pct+'%"></i></div><small>'+mission.progress+' / '+mission.target+' CONCLUÍDO'+(mission.target>1?'S':'')+'</small></article>'}
function missionsPage(){if(ensureMissions())save();const weekly=missionTab==='weekly',list=state.missions[weekly?'weekly':'daily'],remain=nextMissionReset(weekly?'weekly':'daily');$('#view').innerHTML=heading('DESAFIOS DA ESTRADA','Missões','Complete objetivos de entrega e dispute o ranking de pontos.')+'<div class="mission-summary"><div><span>SEUS PONTOS DE MISSÃO</span><b>'+state.missionPoints+'</b></div><small>'+(weekly?'REINÍCIO NA PRÓXIMA QUARTA-FEIRA':'REINÍCIO À MEIA-NOITE')+' · HORÁRIO DE BRASÍLIA<br><strong>'+formatTime(remain)+'</strong> restantes</small></div><nav class="page-tabs"><button data-mission-tab="daily" class="'+(!weekly?'active':'')+'">MISSÕES DIÁRIAS</button><button data-mission-tab="weekly" class="'+(weekly?'active':'')+'">MISSÕES SEMANAIS</button></nav><section class="mission-grid">'+list.map(item=>missionCard(item,weekly?5:1)).join('')+'</section>';document.querySelectorAll('[data-mission-tab]').forEach(button=>button.onclick=()=>{missionTab=button.dataset.missionTab;missionsPage()})}function profile(){const p=progress(),name=user.displayName||'Motorista';$('#view').innerHTML=heading('CARTEIRA PROFISSIONAL','Meu perfil','Seu histórico e evolução como motorista.')+'<div class="profile-grid"><aside class="panel identity"><img class="avatar" src="'+(user.photoURL||avatar(name))+'" alt=""><h2>'+name+'</h2><p>REGISTRO RL-'+user.uid.slice(0,8).toUpperCase()+'</p><div class="profile-data"><div><span>Localização atual</span><b>'+cityLabel(state.city)+'</b></div><div><span>Saldo</span><b>'+money(state.balance)+'</b></div><div><span>Entregas</span><b>'+state.deliveries+'</b></div><div><span>Distância</span><b>'+state.km+' km</b></div></div><button class="logout-button" type="button" data-logout>SAIR DA CONTA</button></aside><section class="panel profile-main"><h2>PROGRESSÃO DO MOTORISTA</h2><div class="level-row"><div><span>NÍVEL ATUAL</span><b>'+p.l+'</b></div><span>'+p.now+' / '+p.need+' XP</span></div><div class="xpbar"><i style="width:'+p.pct+'%"></i></div><div class="progress-label"><span>'+p.pct+'% concluído</span><span>Progressão infinita e lenta</span></div><div class="milestones"><h2>PLANO DE CARREIRA</h2><div class="milestone done"><i></i><div><b>Motorista contratado</b><small>Entregas com veículo fornecido pela empresa.</small></div></div><div class="milestone '+(p.l>=10?'done':'')+'"><i></i><div><b>Comprar o primeiro caminhão · Nível 10</b><small>Tenha seu veículo e receba uma parcela maior do frete.</small></div></div><div class="milestone '+(p.l>=25?'done':'')+'"><i></i><div><b>Abrir transportadora · Nível 25</b><small>Contrate motoristas e administre sua própria empresa.</small></div></div></div></section></div>';document.querySelector('[data-logout]').onclick=logout}
function financialEntries(){const entries=[...(Array.isArray(state.ledger)?state.ledger:[])],refs=new Set(entries.map(item=>item.ref).filter(Boolean));(state.history||[]).forEach((trip,index)=>{const ref=trip.id?'delivery-'+trip.id:'legacy-delivery-'+index;if(!refs.has(ref))entries.push({id:ref,type:'credit',amount:Number(trip.pay)||0,title:'Pagamento de entrega',details:(trip.company?trip.company+' · ':'')+(trip.from||'?')+' → '+(trip.to||'?')+' · '+(trip.km||0)+' km',at:trip.at||0,ref,legacy:true})});if(state.loan&&state.loan.principal&&!entries.some(item=>item.ref==='loan-credit'))entries.push({id:'legacy-loan',type:'credit',amount:Number(state.loan.principal)||45000,title:'Empréstimo bancário',details:'Crédito recuperado do contrato atual.',at:0,ref:'loan-credit',legacy:true});for(const id of ownedTruckIds()){const truck=truckCatalog[id],purchaseRefs=id==='agrale8500'?['truck-agrale','truck-agrale8500']:['truck-'+id];if(!entries.some(item=>purchaseRefs.includes(item.ref)))entries.push({id:'legacy-truck-'+id,type:'debit',amount:truck.price,title:'Compra do '+truck.name,details:'Aquisição recuperada do patrimônio da conta.',at:0,ref:purchaseRefs[0],legacy:true})};return entries.sort((a,b)=>(Number(b.at)||0)-(Number(a.at)||0))}
function balancePage(){const entries=financialEntries(),income=entries.filter(item=>item.type==='credit').reduce((sum,item)=>sum+item.amount,0),expense=entries.filter(item=>item.type==='debit').reduce((sum,item)=>sum+item.amount,0),formatDate=at=>at?new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'}).format(new Date(at)):'REGISTRO ANTIGO';$('#view').innerHTML=heading('CONTROLE FINANCEIRO','Saldo','Veja de onde o dinheiro entrou, onde foi gasto e o histórico recuperado da sua carreira.')+'<section class="balance-summary"><article><span>SALDO DISPONÍVEL</span><b>'+money(state.balance)+'</b><small>Valor atual da conta</small></article><article><span>TOTAL DE ENTRADAS</span><b class="credit">+'+money(income)+'</b><small>'+entries.filter(item=>item.type==='credit').length+' movimentações recuperadas</small></article><article><span>TOTAL DE SAÍDAS</span><b class="debit">-'+money(expense)+'</b><small>'+entries.filter(item=>item.type==='debit').length+' movimentações recuperadas</small></article></section><section class="statement"><header><div><p class="eyebrow">EXTRATO DA CARREIRA</p><h2>Histórico do saldo</h2></div><span>'+entries.length+' LANÇAMENTOS</span></header><div class="statement-list">'+(entries.length?entries.map(item=>'<article class="statement-row '+item.type+'"><i>'+(item.type==='credit'?'↗':'↙')+'</i><div><b>'+escapeHTML(item.title)+'</b><p>'+escapeHTML(item.details||'Movimentação da conta')+'</p><small>'+formatDate(item.at)+(item.legacy?' · HISTÓRICO RECUPERADO':'')+'</small></div><strong>'+(item.type==='credit'?'+':'-')+money(item.amount)+'</strong></article>').join(''):'<div class="statement-empty">Nenhuma movimentação registrada ainda.</div>')+'</div></section>'}
function truckPage(){const vehicle={name:'O Velho Companheiro',year:'1994',odometer:'684.230 km',range:'100 km',condition:'Usado · operacional'};$('#view').innerHTML=heading('VEÍCULO ATUAL','Meu caminhão','O primeiro capítulo da sua história na estrada.')+'<section class="truck-page"><div class="inherited-truck"><img src="assets/trucks/caminhao-herdado.png" alt="Caminhão antigo e usado emprestado pela tia do jogador"><span>EMPRESTADO PELA SUA TIA</span></div><aside class="truck-story"><p class="eyebrow">UMA CHANCE EM FAMÍLIA</p><h2>'+vehicle.name+'</h2><p>Este caminhão pertenceu ao seu tio, um caminhoneiro que passou boa parte da vida cruzando as estradas do Brasil. Depois que ele faleceu, sua tia guardou o veículo por algum tempo. Sabendo que você queria começar uma carreira, ela decidiu emprestá-lo para que o velho companheiro voltasse à estrada.</p><p>O acordo é simples: você cuida do caminhão e paga <strong>R$ 700,00 por semana</strong> pelo empréstimo. Assim poderá juntar dinheiro e, no futuro, comprar seu próprio veículo.</p><dl><div><dt>PROPRIETÁRIA</dt><dd>Sua tia</dd></div><div><dt>COBRANÇA</dt><dd>Todo sábado</dd></div><div><dt>ALUGUEL SEMANAL</dt><dd>'+money(700)+'</dd></div><div><dt>ANO</dt><dd>'+vehicle.year+'</dd></div><div><dt>QUILOMETRAGEM</dt><dd>'+vehicle.odometer+'</dd></div><div><dt>CONDIÇÃO</dt><dd>'+vehicle.condition+'</dd></div><div class="range-row"><dt>ALCANCE MÁXIMO</dt><dd>'+vehicle.range+'</dd></div></dl><div class="truck-warning"><b>ALCANCE LIMITADO</b><span>Contratos acima de 100 km não aparecem no mercado enquanto este for seu caminhão.</span></div><button data-jobs>PROCURAR TRABALHOS</button></aside></section>';bind()}
function rankingList(players,type,companyCode){const value=player=>type==='assets'?Number(player.assets)||0:type==='km'?Number(player.km)||0:type==='missions'?Number(player.missionPoints)||0:type==='companies'?Number(player.companyReputation?.[companyCode])||0:Number(player.level)||1,sorted=[...players].sort((a,b)=>value(b)-value(a));return sorted.length?sorted.slice(0,50).map((player,index)=>{const reputation=type==='companies'?companyReputationProgress(value(player)):null;return'<article class="rank-player '+(player.uid===user.uid?'is-you':'')+'"><b class="rank-position">'+(index+1)+'</b><img src="'+(player.photo||avatar(player.name))+'" alt=""><div><strong>'+escapeHTML(player.name)+(player.uid===user.uid?' (você)':'')+'</strong><small>'+escapeHTML(cityLabel(player.city))+' · '+escapeHTML(player.status||'Offline')+'</small></div><span>'+(type==='assets'?money(value(player)):type==='km'?value(player).toLocaleString('pt-BR')+' km':type==='missions'?value(player)+' pts':type==='companies'?'Nível '+reputation.level+' · '+reputation.points+' entregas':'Nível '+value(player))+'</span></article>'}).join(''):'<p class="ranking-empty">Nenhum motorista registrado ainda.</p>'}
function ranking(){if(rankingTab==='money')rankingTab='assets';const companies=famousCompanies(),selected=companies.find(company=>company.code===rankingCompanyCode)||companies[0];rankingCompanyCode=selected?.code||'CC';const current={uid:user.uid,name:user.displayName||'Motorista',photo:user.photoURL||'',level:level(state.xp),assets:purchasedAssetsValue(),km:state.km,deliveries:state.deliveries,truck:currentTruck().name,missionPoints:Number(state.missionPoints)||0,companyReputation:state.companyReputation&&typeof state.companyReputation==='object'?state.companyReputation:{},city:state.city,status:state.trip?'Em viagem':'Online'},players=allPlayers.some(player=>player.uid===user.uid)?allPlayers.map(player=>player.uid===user.uid?{...player,...current}:player):[current,...allPlayers],boards={assets:{tag:'IMPÉRIOS DA ESTRADA',title:'Maior patrimônio',icon:'R$'},level:{tag:'LENDAS DO ASFALTO',title:'Maior nível',icon:'XP'},km:{tag:'REIS DA RODOVIA',title:'Maior distância',icon:'KM'},missions:{tag:'DESAFIOS CONCLUÍDOS',title:'Pontos de missão',icon:'PTS'},companies:{tag:'REPUTAÇÃO EMPRESARIAL',title:selected?.name||'Empresa',icon:selected?.code||'RP'}},board=boards[rankingTab]||boards.assets,companySelector=rankingTab==='companies'?'<section class="ranking-company-picker"><label for="ranking-company">SELECIONE A EMPRESA</label><select id="ranking-company">'+companies.map(company=>'<option value="'+company.code+'" '+(company.code===rankingCompanyCode?'selected':'')+'>'+escapeHTML(company.name)+'</option>').join('')+'</select><small>O ranking considera o nível e as entregas concluídas para esta empresa.</small></section>':'';$('#view').innerHTML=heading('CARREIRA COMPETITIVA','Ranking dos motoristas',rankingTab==='companies'?'Compare sua reputação em cada empresa com os demais jogadores.':'Patrimônio considera somente caminhões, galpões e mercadorias realmente comprados.')+'<nav class="page-tabs ranking-tabs"><button data-ranking-tab="assets" class="'+(rankingTab==='assets'?'active':'')+'">PATRIMÔNIO</button><button data-ranking-tab="level" class="'+(rankingTab==='level'?'active':'')+'">NÍVEL</button><button data-ranking-tab="km" class="'+(rankingTab==='km'?'active':'')+'">DISTÂNCIA</button><button data-ranking-tab="missions" class="'+(rankingTab==='missions'?'active':'')+'">MISSÕES</button><button data-ranking-tab="companies" class="'+(rankingTab==='companies'?'active':'')+'">EMPRESAS</button></nav>'+companySelector+'<section class="ranking-single"><div class="ranking-board '+(rankingTab==='missions'||rankingTab==='companies'?'mission-ranking':'')+'"><header><div><span>'+board.tag+'</span><h2>'+escapeHTML(board.title)+'</h2></div><b>'+escapeHTML(board.icon)+'</b></header><div class="ranking-list">'+rankingList(players,rankingTab,rankingCompanyCode)+'</div></div></section>';document.querySelectorAll('[data-ranking-tab]').forEach(button=>button.onclick=()=>{rankingTab=button.dataset.rankingTab;ranking()});document.querySelector('#ranking-company')?.addEventListener('change',event=>{rankingCompanyCode=event.target.value;ranking()})}function truckPageV2(){ensureFuel();const truck=currentTruck(),borrowed=state.truck==='tia',conditions=truckTab==='conditions',inventory=truckTab==='inventory',tabs='<nav class="page-tabs truck-tabs"><button data-truck-tab="basic" class="'+(!conditions&&!inventory?'active':'')+'">INFORMAÇÕES BÁSICAS</button><button data-truck-tab="conditions" class="'+(conditions?'active':'')+'">CONDIÇÕES DO CAMINHÃO</button><button data-truck-tab="inventory" class="'+(inventory?'active':'')+'">INVENTÁRIO DE PALETES</button></nav>';const basic='<section class="truck-page"><div class="inherited-truck"><img src="'+truck.image+'" alt="'+truck.name+'"><span>'+(borrowed?'EMPRESTADO PELA SUA TIA':'VEÍCULO PRÓPRIO')+'</span></div><aside class="truck-story"><p class="eyebrow">'+(borrowed?'UMA CHANCE EM FAMÍLIA':'PATRIMÔNIO DO MOTORISTA')+'</p><h2>'+truck.name+'</h2><p>'+(borrowed?'Depois que seu tio faleceu, sua tia emprestou o antigo caminhão para você começar. O acordo custa R$ 700,00 por semana e termina quando você compra seu próprio veículo.':truck.description)+'</p><dl><div><dt>PROPRIEDADE</dt><dd>'+(borrowed?'Sua tia':'Sua')+'</dd></div><div><dt>ALCANCE OPERACIONAL</dt><dd>'+truck.range+' km</dd></div><div><dt>VELOCIDADE MÁXIMA</dt><dd>'+truck.speed+' km/h</dd></div><div><dt>CAPACIDADE DE PALETES</dt><dd>'+truck.pallets+' paletes</dd></div><div><dt>BÔNUS POR CAPACIDADE</dt><dd>'+(truck.pallets>1?'+'+((truck.pallets-1)*25)+'% no frete':'Frete normal')+'</dd></div>'+(borrowed?'<div><dt>ALUGUEL</dt><dd>'+money(700)+' / semana</dd></div>':'<div><dt>MODELO</dt><dd>'+truck.model+'</dd></div>')+'</dl><button data-jobs>PROCURAR TRABALHOS</button></aside></section>';const conditionPage='<section class="truck-condition-page"><header><div><p class="eyebrow">MANUTENÇÃO E ABASTECIMENTO</p><h2>'+truck.name+'</h2><p>Acompanhe pneus e combustível antes de iniciar uma nova rota.</p></div><div class="condition-summary"><span>CONDIÇÃO PARA VIAJAR</span><b>'+(tireCondition()<=0?'BLOQUEADO':fuelLevel()<=0?'SEM COMBUSTÍVEL':'OPERACIONAL')+'</b></div></header><div class="truck-condition-grid">'+tirePanelHTML()+fuelPanelHTML()+'</div></section>';const inventoryPage='<section class="truck-inventory-page"><header><div><p class="eyebrow">CARGA PRÓPRIA</p><h2>Inventário do caminhão</h2><p>A capacidade de paletes varia conforme o caminhão em uso. Movimente os produtos pelos galpões das cidades.</p></div><b>'+truckPalletCount()+' / '+truckPalletLimit()+' OCUPADOS</b></header>'+(state.trip&&!state.trip.freeTrip?deliveryCargoVisual(state.trip.company==='Coca-Cola FEMSA'?'CC':state.trip.company==='Klabin'?'KL':state.trip.company==='Fini · Sánchez Cano'?'FI':state.trip.company==='Bosch'?'BO':state.trip.company==='Pirelli'?'PI':''):'' )+palletInventoryHTML(state.truckPallets,truckPalletLimit())+'</section>';$('#view').innerHTML=heading('VEÍCULO ATUAL','Meu caminhão',inventory?'Confira os pallets carregados e os espaços disponíveis.':conditions?'Gerencie o estado do veículo e prepare a próxima viagem.':borrowed?'O caminhão emprestado que iniciou sua carreira.':'Seu primeiro caminhão próprio.')+tabs+(inventory?inventoryPage:conditions?conditionPage:basic);bind();document.querySelectorAll('[data-truck-tab]').forEach(button=>button.onclick=()=>{truckTab=button.dataset.truckTab;truckPageV2()});document.querySelector('[data-replace-tires]')?.addEventListener('click',replaceTires);document.querySelector('[data-refuel]')?.addEventListener('click',refuelTruck)}

const loanPlans={8:{rate:.08},16:{rate:.18},24:{rate:.30},36:{rate:.48}};function loanQuote(weeks){const plan=loanPlans[weeks],total=Math.round(45000*(1+plan.rate)),weekly=Math.ceil(total/weeks);return{weeks:+weeks,rate:plan.rate,total,weekly}}
function truckShop(){const saleIds=['agrale8500','mercedes710','volkswagen8150','scaniaT113'],cards=saleIds.map(id=>{const truck=truckCatalog[id],owned=ownsTruck(id),active=state.truck===id,label=active?'CAMINHÃO EM USO':owned?'USAR ESTE CAMINHÃO':'COMPRAR POR '+money(truck.price);return'<section class="dealer-card"><div class="dealer-photo"><img src="'+truck.image+'" alt="'+truck.name+'"><span>SEMINOVO</span></div><div class="dealer-info"><p class="eyebrow">'+(id==='scaniaT113'?'CAMINHÃO RODOVIÁRIO · 4X2':'CAMINHÃO LEVE · 4X2')+'</p><h2>'+truck.name+'</h2><strong class="dealer-price">'+money(truck.price)+'</strong><p>'+truck.description+'</p><dl><div><dt>ALCANCE NO JOGO</dt><dd>'+truck.range+' km</dd></div><div><dt>VELOCIDADE MÁXIMA</dt><dd>'+truck.speed+' km/h</dd></div><div><dt>CAPACIDADE DE PALETES</dt><dd>'+truck.pallets+' paletes</dd></div><div><dt>BÔNUS NO FRETE</dt><dd>'+(truck.pallets>1?'+'+((truck.pallets-1)*25)+'%':'Normal')+'</dd></div><div><dt>TANQUE DE COMBUSTÍVEL</dt><dd>'+truck.fuelCapacity+' litros</dd></div></dl><button data-dealer-truck="'+id+'" '+(active?'disabled':'')+'>'+label+'</button><small>Seu saldo atual: '+money(state.balance)+'</small></div></section>'}).join('');$('#view').innerHTML=heading('CONCESSIONÁRIA LONER','Venda de caminhões','Compre veículos para aumentar sua capacidade e abrir novas rotas.')+'<div class="dealer-list">'+cards+'</div>';document.querySelectorAll('[data-dealer-truck]').forEach(button=>button.onclick=()=>selectOrBuyTruck(button.dataset.dealerTruck))}
function selectOrBuyTruck(id){if(state.trip){toast('Conclua a viagem antes de trocar ou comprar outro caminhão.');return}const truck=truckCatalog[id];if(!truck?.owned||state.truck===id)return;if(truckPalletCount()>truck.pallets){toast('Descarregue '+(truckPalletCount()-truck.pallets)+' palete'+(truckPalletCount()-truck.pallets>1?'s':'')+' antes de trocar para este caminhão.');return}if(ownsTruck(id)){state.truck=id;ensureFuel();save();toast(truck.name+' selecionado.');truckShop();return}if(state.balance<truck.price){toast('Saldo insuficiente para comprar o '+truck.name+'.');return}state.balance-=truck.price;state.ownedTrucks=[...ownedTruckIds(),id];state.truck=id;state.tires={tia:100,agrale8500:100,mercedes710:100,volkswagen8150:100,...(state.tires||{}),[id]:100};ensureFuel();state.fuel[id]=truck.fuelCapacity;addLedger('debit',truck.price,'Compra do '+truck.name,'Caminhão próprio registrado na sua transportadora.',Date.now(),'truck-'+id);save();toast(truck.name+' comprado! O veículo já está em uso.');truckShop()}
function bankPage(){const active=state.loan?.active,quote=loanQuote(8);$('#view').innerHTML=heading('BANCO LONER','Crédito para crescer','Financiamento semanal para comprar seu primeiro caminhão.')+(active?'<section class="loan-active"><p class="eyebrow">EMPRÉSTIMO ATIVO</p><h2>'+money(state.loan.remainingBalance)+'</h2><span>SALDO DEVEDOR</span><div><b>'+state.loan.remainingWeeks+'</b><small>PARCELAS RESTANTES</small></div><div><b>'+money(state.loan.weekly)+'</b><small>TODO SÁBADO</small></div><p>As parcelas são cobradas mesmo quando seu saldo estiver insuficiente.</p></section>':'<section class="bank-offer"><div><p class="eyebrow">CRÉDITO PRÉ-APROVADO</p><h2>'+money(45000)+'</h2><p>Escolha o prazo. Quanto maior o número de semanas, maiores serão os juros totais.</p></div><aside><label for="loan-weeks">PRAZO DE PAGAMENTO</label><select id="loan-weeks"><option value="8">8 semanas · 8% de juros</option><option value="16">16 semanas · 18% de juros</option><option value="24">24 semanas · 30% de juros</option><option value="36">36 semanas · 48% de juros</option></select><dl><div><dt>VALOR RECEBIDO</dt><dd>'+money(45000)+'</dd></div><div><dt>TOTAL A PAGAR</dt><dd id="loan-total">'+money(quote.total)+'</dd></div><div><dt>PARCELA SEMANAL</dt><dd id="loan-weekly">'+money(quote.weekly)+'</dd></div></dl><button data-take-loan>CONTRATAR EMPRÉSTIMO</button><small>Débito automático todos os sábados. O saldo poderá ficar negativo.</small></aside></section>');const select=$('#loan-weeks');if(select)select.onchange=()=>{const q=loanQuote(select.value);$('#loan-total').textContent=money(q.total);$('#loan-weekly').textContent=money(q.weekly)};document.querySelector('[data-take-loan]')?.addEventListener('click',takeLoan)}
function takeLoan(){if(state.loan?.active)return;const q=loanQuote($('#loan-weeks').value),p=brazilNow(),today=p.year+'-'+p.month+'-'+p.day;state.balance+=45000;state.loan={active:true,principal:45000,total:q.total,weekly:q.weekly,remainingBalance:q.total,remainingWeeks:q.weeks,rate:q.rate,paidOn:p.weekday==='Sat'?today:''};addLedger('credit',45000,'Empréstimo bancário',q.weeks+' parcelas semanais · total contratado '+money(q.total),Date.now(),'loan-credit');save();toast('Empréstimo aprovado: '+money(45000)+' adicionados ao saldo.');bankPage()}
function companyPage(){if(!state.companyName){$('#view').innerHTML=heading('SEU PRÓXIMO PASSO','Criar minha empresa','Escolha o nome definitivo da sua transportadora para abrir a página dela.')+'<section class="company-create"><div class="company-create-mark">RL</div><div><p class="eyebrow">FUNDAÇÃO DA TRANSPORTADORA</p><h2>Dê um nome ao seu futuro</h2><p>O nome será registrado nesta conta e aparecerá na página da sua empresa.</p><form id="company-form"><label for="company-name">NOME DA EMPRESA</label><input id="company-name" maxlength="32" minlength="3" autocomplete="organization" placeholder="Ex.: Horizonte Transportes" required><small>Use de 3 a 32 caracteres.</small><button type="submit">CRIAR MINHA EMPRESA</button></form></div></section>';$('#company-form').onsubmit=event=>{event.preventDefault();const name=$('#company-name').value.trim().replace(/\s+/g,' ');if(name.length<3){toast('Digite um nome com pelo menos 3 caracteres.');return}state.companyName=name.slice(0,32);save();toast('Transportadora criada com sucesso!');companyPage()};return}const ownedTrucks=ownedTruckIds().length,name=escapeHTML(state.companyName),initials=state.companyName.split(/\s+/).slice(0,2).map(word=>word[0]).join('').toUpperCase();$('#view').innerHTML=heading('GESTÃO DA TRANSPORTADORA',name,'Acompanhe o patrimônio e o crescimento da sua empresa.')+'<section class="company-dashboard"><header><div class="company-emblem">'+escapeHTML(initials)+'</div><div><span>TRANSPORTADORA DO JOGADOR</span><h2>'+name+'</h2><p>Fundador: '+escapeHTML(user.displayName||'Motorista')+'</p></div></header><div class="company-stats"><article><span>CAMINHÕES REGISTRADOS</span><b>'+ownedTrucks+'</b><small>Somente veículos próprios entram na frota</small></article><article><span>MOTORISTAS CONTRATADOS</span><b>0</b><small>Você ainda trabalha sozinho</small></article><article><span>QUILÔMETROS DA EMPRESA</span><b>'+Number(state.km).toLocaleString('pt-BR')+'</b><small>km percorridos pelo fundador</small></article></div><div class="company-fleet"><div><p class="eyebrow">FROTA DA EMPRESA</p><h3>'+(ownedTrucks?ownedTrucks+' caminhão'+(ownedTrucks===1?' registrado':'s registrados'):'Nenhum caminhão registrado')+'</h3><p>'+(ownedTrucks?'Sua frota própria está registrada no patrimônio da transportadora: '+ownedTruckIds().map(id=>truckCatalog[id].name).join(', ')+'.':'O caminhão da sua tia é emprestado e não pertence à empresa. Compre um veículo próprio para iniciar a frota.')+'</p></div><button data-company-shop>VER CAMINHÕES À VENDA</button></div></section>';document.querySelector('[data-company-shop]').onclick=()=>location.hash='concessionaria'}
function updateOfferClock(){const remain=nextMissionReset('daily'),total=Math.max(0,Math.floor(remain/1000)),hours=Math.floor(total/3600),minutes=Math.floor(total%3600/60),seconds=total%60,display=$('#offer-reset'),validUntil=$('#offer-valid-until');if(display)display.textContent=String(hours).padStart(2,'0')+':'+String(minutes).padStart(2,'0')+':'+String(seconds).padStart(2,'0');if(validUntil)validUntil.textContent=nextOfferHour();if(location.hash==='#entregas'&&activeOfferKey&&activeOfferKey!==offerCycleKey())deliveries()}
