async function routePreviewPage(){let offer;try{offer=JSON.parse(sessionStorage.getItem('rota-loner-preview'))}catch{}if(!offer||!cities[offer.from]||!cities[offer.to]){location.hash='entregas';return}const start=cities[offer.from],end=cities[offer.to];$('#view').innerHTML=heading('PLANEJAMENTO DE ROTA','Prévia da viagem','Confira o caminho antes de aceitar o trabalho.')+'<section class="preview-map-shell"><div class="preview-contract">'+companyLogo(offer.company,true)+'<div><span>ROTA PREVISTA</span><h2>'+offer.from+' → '+offer.to+'</h2><p>'+offer.cargo+'</p></div><dl><div><dt>DISTÂNCIA</dt><dd>'+offer.km+' km</dd></div><div><dt>TEMPO ESTIMADO</dt><dd>'+travelTime(offer.km)+'</dd></div><div><dt>FRETE</dt><dd>'+money(marketReward(offer.km,offer.company.code).pay)+'</dd></div><div><dt>COMBUSTÍVEL</dt><dd>+'+money(fuelCostFor(offer.km))+'</dd></div></dl><button data-preview-back>VOLTAR ÀS OFERTAS</button></div><div id="preview-map"></div></section>';document.querySelector('[data-preview-back]').onclick=()=>location.hash='entregas';if(!window.L){$('#preview-map').innerHTML='<p class="map-error">Não foi possível carregar o mapa.</p>';return}activeMap=L.map('preview-map',{zoomControl:true,minZoom:5,maxZoom:16}).setView([start.lat,start.lng],9);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(activeMap);L.marker([start.lat,start.lng]).addTo(activeMap).bindTooltip('Origem · '+offer.from,{permanent:true,direction:'top'});L.marker([end.lat,end.lng]).addTo(activeMap).bindTooltip('Destino · '+offer.to,{permanent:true,direction:'top'});let path=[[start.lat,start.lng],[end.lat,end.lng]];try{const response=await fetch('https://router.project-osrm.org/route/v1/driving/'+start.lng+','+start.lat+';'+end.lng+','+end.lat+'?overview=full&geometries=geojson'),data=await response.json();if(data.routes?.[0])path=data.routes[0].geometry.coordinates.map(c=>[c[1],c[0]])}catch{}if(location.hash!=='#previsao'||!activeMap)return;L.polyline(path,{color:'#c5f24a',weight:5,opacity:.9}).addTo(activeMap);activeMap.fitBounds(L.latLngBounds(path),{padding:[45,45]});setTimeout(()=>activeMap?.invalidateSize(),50)}
