async function startFreeTrip(destination,button){if(state.trip)return;if(tireCondition()<=0){toast('Os pneus estão em 0%. Troque-os na página do caminhão antes de viajar.');return}const direct=(routes[state.city]||[]).find(route=>route.to===destination),truck=currentTruck();if(!direct){toast('Não existe uma rota direta para esta cidade.');return}if(direct.km>truck.range){toast('Seu caminhão não possui alcance para esta viagem livre.');return}if(!canFuelTrip(direct.km,truck)){toast('Combustível insuficiente. Abasteça na aba Condições do caminhão.');return}const from=state.city,startCity=cities[from],endCity=cities[destination];if(!startCity||!endCity){toast('A rota possui uma cidade inválida. Atualize a página e tente novamente.');return}if(button){button.disabled=true;button.textContent='CALCULANDO ROTA...'}let path=[[startCity.lat,startCity.lng],[endCity.lat,endCity.lng]];try{const response=await fetch('https://router.project-osrm.org/route/v1/driving/'+startCity.lng+','+startCity.lat+';'+endCity.lng+','+endCity.lat+'?overview=full&geometries=geojson'),data=await response.json(),road=data.routes?.[0];if(road)path=road.geometry.coordinates.map(point=>[point[1],point[0]])}catch{}const start=Date.now(),carryingPallets=truckPalletCount()>0,duration=Math.max(15,Math.round(travelMinutes(direct.km)*(carryingPallets?1:.75))),fuelStart=fuelLevel(),fuelPlanned=fuelLitersFor(direct.km,truck),fuelUsed=0;state.trip={freeTrip:true,palletTrip:carryingPallets,fuelStart,fuelPlanned,fuelUsed,truckId:state.truck,tireCondition:tireCondition(),from,to:destination,company:carryingPallets?'Coca-Cola FEMSA':'',cargo:carryingPallets?truckPalletCount()+' palete'+(truckPalletCount()>1?'s':'')+' de Coca-Cola':'Sem mercadoria',totalKm:direct.km,path,start,end:start+duration*60000,pay:0,xp:0};save();toast(carryingPallets?'Transporte de pallets iniciado para '+destination+'.':'Viagem livre iniciada para '+destination+'. Você chegará 25% mais rápido.');location.hash='mapa'}async function startTrip(i,button){if(state.trip)return;if(truckPalletCount()){toast('Descarregue ou venda os pallets antes de aceitar um frete.');return}if(tireCondition()<=0){toast('Os pneus estão em 0%. Troque-os na página do caminhão antes de aceitar uma entrega.');return}const r=currentOffers[i],truck=currentTruck();if(!r){deliveries();toast('Esta oferta não está mais disponível. Escolha outra entrega.');return}if(r.km>truck.range){toast('Esta rota exige alcance de '+r.km+' km. Seu caminhão alcança até '+truck.range+' km.');return}if(!canFuelTrip(r.km,truck)){toast('Combustível insuficiente. Abasteça na aba Condições do caminhão.');return}if(r.offerKey!==offerCycleKey()){deliveries();toast('As ofertas foram renovadas. Escolha um novo trabalho.');return}const from=state.city,startCity=cities[from],endCity=cities[r.to];if(!startCity||!endCity){deliveries();toast('A rota possui uma cidade inválida e foi renovada. Escolha outra entrega.');return}if(button){button.disabled=true;button.textContent='RESERVANDO ENTREGA...'}try{await claimGlobalOffer(r,from)}catch(error){console.warn('Falha ao reservar entrega:',error);if(button){button.disabled=false;button.textContent='ACEITAR ENTREGA'}deliveries();const code=String(error?.code||'');toast(error?.message==='offer-unavailable'?'Outro jogador já escolheu esta entrega.':code.includes('permission-denied')?'O mercado de fretes precisa das regras atualizadas no servidor.':code.includes('unavailable')||code.includes('failed-precondition')?'O mercado está temporariamente indisponível. Tente novamente em instantes.':'Não foi possível reservar esta entrega agora. Verifique sua conexão.');return}if(button)button.textContent='CALCULANDO ROTA...';let path=[[startCity.lat,startCity.lng],[endCity.lat,endCity.lng]],totalKm=r.km;try{const res=await fetch('https://router.project-osrm.org/route/v1/driving/'+startCity.lng+','+startCity.lat+';'+endCity.lng+','+endCity.lat+'?overview=full&geometries=geojson'),data=await res.json(),road=data.routes?.[0];if(road)path=road.geometry.coordinates.map(c=>[c[1],c[0]])}catch{}const rw=marketReward(totalKm,r.company.code),start=Date.now(),duration=travelMinutes(totalKm),fuelStart=fuelLevel(),fuelPlanned=fuelLitersFor(totalKm,truck),fuelUsed=0,fuelAllowance=fuelCostFor(totalKm,truck);state.trip={truckId:state.truck,fuelStart,fuelPlanned,tireCondition:tireCondition(),from,to:r.to,company:r.company.name,cargo:r.cargo,totalKm,path,start,end:start+duration*60000,pay:rw.pay,fuelUsed,fuelAllowance,xp:rw.xp};save();toast('Frete da '+r.company.name+' iniciado para '+r.to+'. Tempo estimado: '+travelTime(totalKm)+'.');location.hash='mapa'}
function finishTrip(){if(!state.trip)return;updateTripFuel(true);const t=state.trip,id=crypto.randomUUID?.()||String(Date.now()),at=Date.now(),condition=applyTireWear(t.totalKm,t.truckId||state.truck);if(t.freeTrip){state.km+=t.totalKm;state.city=t.to;state.trip=null;save();clearInterval(mapTimer);toast((t.palletTrip?'Transporte de pallets concluído! Você chegou a ':'Viagem livre concluída! Você chegou a ')+t.to+'. Pneus: '+condition.toFixed(1).replace('.',',')+'%.');location.hash='home';return}state.xp+=t.xp;state.balance+=t.pay+(Number(t.fuelAllowance)||0);state.deliveries++;state.km+=t.totalKm;state.city=t.to;state.history.unshift({id,from:t.from,to:t.to,company:t.company,cargo:t.cargo,km:t.totalKm,pay:t.pay,at});addLedger('credit',t.pay,'Pagamento de entrega',t.company+' · '+t.from+' → '+t.to+' · '+t.totalKm+' km',at,'delivery-'+id);if(Number(t.fuelAllowance)>0)addLedger('credit',t.fuelAllowance,'Auxílio-combustível da empresa',t.company+' · '+Number(t.fuelUsed||0).toFixed(2).replace('.',',')+' L de diesel S10 · '+t.totalKm+' km',at,'fuel-allowance-'+id);const missionReward=updateMissions(t),reputationReward=addCompanyReputation(t.company);state.trip=null;save();clearInterval(mapTimer);toast('Entrega concluída! Você chegou a '+t.to+': +'+t.xp+' XP e '+money(t.pay)+' · combustível '+money(Number(t.fuelAllowance)||0)+(missionReward?' · +'+missionReward+' pontos de missão':'')+(reputationReward?' · reputação '+reputationReward.company+' nível '+reputationReward.level:'')+' · pneus '+condition.toFixed(1).replace('.',',')+'%.');location.hash='home'}
function versionPage(){$('#view').innerHTML=heading('HISTÓRICO DE DESENVOLVIMENTO','Loner v.0.0.26','Acompanhe as novidades e melhorias adicionadas ao jogo.')+'<section class="release-current"><span>VERSÃO ATUAL</span><h2>v.0.0.26</h2><p>Missões, economia dinâmica, expansão do mapa e sincronização entre dispositivos.</p></section><section class="changelog"><article><time>v.0.0.26 · ATUAL</time><h3>Missões e mercado dinâmico</h3><ul><li>Missões diárias e semanais aleatórias com pontos próprios e reinícios pelo horário de Brasília.</li><li>Novo ranking de missões e separação das classificações por abas.</li><li>Mercado fictício das 28 principais empresas, influenciado pelas entregas de todos os jogadores.</li><li>Doze ofertas em cada cidade, divididas em quatro faixas de distância, renovadas à meia-noite e repostas após cada aceite.</li><li>Páginas individuais das empresas com contratos, cidades, cargas, distância, duração, pagamento e XP do dia.</li><li>Sistema de diesel S10 com consumo por quilômetro, abastecimento e auxílio-combustível pago pelas empresas.</li><li>Meu caminhão reorganizado em abas de informações básicas e condições de pneus e tanque.</li><li>Volkswagen 8-150 adicionado à concessionária, com suporte a frota própria e troca de veículo ativo.</li></ul></article><article><time>v.0.0.25a–v.0.0.25j</time><h3>Conta, mapa e expansão regional</h3><ul><li>Login Google/Firebase corrigido com perfil, progresso e viagem sincronizados entre dispositivos.</li><li>Botão para sair da conta adicionado ao perfil e relógio de Brasília estabilizado.</li><li>Fotos dos jogadores, cartões da viagem e posição multiplayer aprimorados no mapa.</li><li>Nome da rua ou rodovia atual exibido durante a viagem quando disponível.</li><li>Praia Grande, Mongaguá, Itanhaém, Peruíbe, Juquitiba, Embu das Artes e Miracatu adicionadas com empresas, logos e rotas.</li><li>Página Empresas reorganizada com catálogo, logos e informações completas sem sobreposição.</li></ul></article><article><time>v.0.0.25</time><h3>Viagens multiplayer ao vivo</h3><ul><li>Posição simulada dos jogadores no mapa em tempo real.</li><li>Trajeto rodoviário, foto, tempo e distância restantes.</li><li>Painel ao clicar no motorista com carga, empresa e horário de aceite.</li><li>Sincronização das coordenadas pelo Firebase.</li></ul></article><article><time>v.0.0.24</time><h3>Economia e presença online</h3><ul><li>Nova página Saldo com entradas, saídas e histórico recuperado.</li><li>Ranking por dinheiro, nível e quilômetros percorridos.</li><li>Persistência do progresso entre dispositivos.</li><li>Primeiro sábado isento do aluguel da tia.</li></ul></article><article><time>v.0.0.23</time><h3>Novas cidades e empresas</h3><ul><li>Guarulhos, Cabreúva e São Roque adicionadas ao mapa.</li><li>Novas fábricas, logotipos, cargas e conexões rodoviárias.</li><li>Criação da transportadora própria e controle de frota.</li></ul></article></section>'}
function route(){updateTripFuel();clearInterval(mapTimer);clearInterval(liveDriversTimer);if(activeMap){activeMap.remove();activeMap=null}if(state?.trip&&state.trip.end<=Date.now()){finishTrip();return}if(state&&!state.startCityChosen){startCityPage();$('.sidebar').removeClass?.('open');return}const page=location.hash.slice(1)||'home';document.querySelectorAll('[data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===page));if(page==='empresas')companiesPage();else if(page==='versao')versionPage();else if(page==='perfil')profile();else if(page==='missoes')missionsPage();else if(page==='saldo')balancePage();else if(page==='ranking')ranking();else if(page==='caminhao')truckPageV2();else if(page==='concessionaria')truckShop();else if(page==='banco')bankPage();else if(page==='entregas'||page==='empresa/coca-cola')deliveries();else if(page==='previsao')routePreviewPage();else if(page==='mapa')mapPage();else if(page.startsWith('jogador/'))playerPage(decodeURIComponent(page.slice(8)));else if(page.startsWith('cidade/'))cityPage(decodeURIComponent(page.slice(7)));else if(page.startsWith('empresa/'))companyDetailsPage(decodeURIComponent(page.slice(8)));else if(page==='empresa')companyPage();else if(state.trip)tripHome();else home();$('.sidebar').classList.remove('open')}
function brazilNow(){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit',weekday:'short',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));return parts}
function updateBrazilClock(){const p=brazilNow(),clock=$('#brasil-clock b');if(clock)clock.textContent=p.day+'/'+p.month+'/'+p.year+' · '+p.hour+':'+p.minute+':'+p.second}
function chargeWeeklyRental(){if(!user||!state)return;const p=brazilNow(),today=p.year+'-'+p.month+'-'+p.day;if(p.weekday!=='Sat')return;state.rentalExemptOn=state.rentalExemptOn||firstSaturdayFromAccount();const charges=[];if(state.truck==='tia'&&today!==state.rentalExemptOn&&state.rentalPaidOn!==today&&state.balance>=700){state.balance-=700;state.rentalPaidOn=today;addLedger('debit',700,'Aluguel semanal da tia','Cobrança automática de sábado.',Date.now(),'rental-'+today);charges.push('aluguel da tia: -'+money(700))}if(state.loan?.active&&state.loan.paidOn!==today){const payment=Math.min(state.loan.weekly,state.loan.remainingBalance);state.balance-=payment;state.loan.remainingBalance=Math.max(0,state.loan.remainingBalance-payment);state.loan.remainingWeeks=Math.max(0,state.loan.remainingWeeks-1);state.loan.paidOn=today;if(state.loan.remainingBalance<=0||state.loan.remainingWeeks<=0)state.loan.active=false;addLedger('debit',payment,'Parcela do banco','Pagamento semanal do empréstimo.',Date.now(),'loan-payment-'+today);charges.push('parcela do banco: -'+money(payment))}if(!charges.length)return;save();toast('Débito de sábado · '+charges.join(' · ')+'.')}
async function enter(u){user=u;state=await restoreProgress();normalizeGameState();if(state.startCityChosen==null)state.startCityChosen=Boolean(state.savedAt||state.deliveries||state.xp||state.km||(state.history||[]).length);ensureMissions();localStorage.setItem(key(),JSON.stringify(state));await syncProgress();$('#login').classList.add('hidden');$('#app').classList.remove('hidden');const rankingLink=document.querySelector('[data-page="ranking"]');if(!document.querySelector('[data-page="saldo"]')){const balanceLink=document.createElement('a');balanceLink.href='#saldo';balanceLink.dataset.page='saldo';balanceLink.innerHTML='<i>R$</i>Saldo';rankingLink.parentNode.insertBefore(balanceLink,rankingLink)}if(!document.querySelector('.sidebar-version')){const versionLink=document.createElement('a');versionLink.href='#versao';versionLink.dataset.page='versao';versionLink.className='sidebar-version';versionLink.innerHTML='<span>VERSÃO DO JOGO</span><b>v.0.0.26</b>';document.querySelector('.side-status').insertAdjacentElement('afterend',versionLink)}document.querySelector('[data-page="mapa"]').lastChild.textContent='Mapa';applyRentalExemption();chrome();syncProgress();watchProgress();watchPresence();watchGameMarket();watchGlobalOffers();route();updateBrazilClock();chargeWeeklyRental();clearInterval(rentalTimer);rentalTimer=setInterval(()=>{updateBrazilClock();updateOfferClock();chargeWeeklyRental();if(offersDay!==offerCycleKey())watchGlobalOffers();if(ensureMissions()){save();if(location.hash==='#missoes')missionsPage()}},1000);document.body.classList.remove('auth-pending')}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),4200)}
async function logout(){try{await syncProgress();await signOut(auth)}catch(error){console.warn('Falha ao sair:',error.code||error.message);toast('Não foi possível sair da conta agora.')}}$('#google-login').onclick=async()=>{try{await setPersistence(auth,browserLocalPersistence);$('#auth-message').textContent='Abrindo o login seguro do Google...';await signInWithPopup(auth,provider)}catch(error){console.warn('Falha no login:',error.code||error.message);const blocked=error.code==='auth/popup-blocked',closed=error.code==='auth/popup-closed-by-user';$('#auth-message').textContent=blocked?'Permita a janela de login do Google e tente novamente.':closed?'Login cancelado. Tente novamente quando quiser.':'Não foi possível entrar. Verifique a conexão e tente novamente.'}};$('#profile-shortcut').onclick=()=>location.hash='perfil';$('#menu-toggle').onclick=()=>$('.sidebar').classList.toggle('open');addEventListener('hashchange',route);updateBrazilClock();clearInterval(clockTimer);clockTimer=setInterval(updateBrazilClock,1000);onAuthStateChanged(auth,u=>{if(u)enter(u).catch(error=>{console.error('Falha ao carregar a conta:',error);$('#auth-message').textContent='Sua conta entrou, mas o perfil não pôde ser carregado. Atualize a página.';document.body.classList.remove('auth-pending')});else{progressStop?.();presenceStop?.();marketStop?.();offerStateStop?.();clearInterval(presenceTimer);clearInterval(rentalTimer);user=null;state=null;$('#app').classList.add('hidden');$('#login').classList.remove('hidden');$('#auth-message').textContent='';document.body.classList.remove('auth-pending')}});
